// MNIST inference CLI: ./cli_tool weights.json image.png
// Prints the predicted digit (0-9) and nothing else.
#include <cJSON.h>
#include "lodepng.h"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

static int fail(const char* msg) {
    fprintf(stderr, "cli_tool: %s\n", msg);
    return 1;
}

static std::vector<char> read_file(const std::string& path) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) return {};
    std::fseek(f, 0, SEEK_END);
    long n = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    std::vector<char> buf((size_t)n);
    size_t got = std::fread(buf.data(), 1, buf.size(), f);
    fclose(f);
    if (got != buf.size()) buf.clear();
    return buf;
}

// Weight matrix: 2D array [rows][cols] stored row-major.
struct Linear {
    int in = 0, out = 0;
    std::vector<double> w;  // out x in
    std::vector<double> b;  // out

    bool load(const cJSON* node) {
        const cJSON* wobj = cJSON_GetObjectItemCaseSensitive(node, "weight");
        const cJSON* bobj = cJSON_GetObjectItemCaseSensitive(node, "bias");
        if (!cJSON_IsArray(wobj) || !cJSON_IsArray(bobj)) return false;
        int rows = cJSON_GetArraySize(wobj);
        if (rows <= 0) return false;
        const cJSON* row0 = cJSON_GetArrayItem(wobj, 0);
        if (!cJSON_IsArray(row0)) return false;
        int cols = cJSON_GetArraySize(row0);
        if (cols <= 0 || cJSON_GetArraySize(bobj) != rows) return false;
        in = cols; out = rows;
        w.resize((size_t)rows * cols);
        b.resize(rows);
        for (int r = 0; r < rows; ++r) {
            const cJSON* row = cJSON_GetArrayItem(wobj, r);
            if (!cJSON_IsArray(row) || cJSON_GetArraySize(row) != cols) return false;
            for (int c = 0; c < cols; ++c) {
                const cJSON* e = cJSON_GetArrayItem(row, c);
                if (!cJSON_IsNumber(e)) return false;
                w[(size_t)r * cols + c] = e->valuedouble;
            }
            const cJSON* be = cJSON_GetArrayItem(bobj, r);
            if (!cJSON_IsNumber(be)) return false;
            b[r] = be->valuedouble;
        }
        return true;
    }

    void apply(const std::vector<double>& x, std::vector<double>& y) const {
        y.resize(out);
        for (int r = 0; r < out; ++r) {
            double s = b[r];
            const double* wr = &w[(size_t)r * in];
            for (int c = 0; c < in; ++c) s += wr[c] * x[c];
            y[r] = s;
        }
    }
};

static void reLu(std::vector<double>& v) {
    for (auto& x : v) if (x < 0.0) x = 0.0;
}

int main(int argc, char** argv) {
    if (argc != 3) return fail("usage: cli_tool weights.json image.png");

    // --- Load weights ---
    std::vector<char> raw = read_file(argv[1]);
    if (raw.empty()) return fail("cannot read weights file");
    cJSON* root = cJSON_ParseWithLength(raw.data(), raw.size());
    if (!root) return fail("invalid weights JSON");

    Linear l1, l2, l3;
    const char* names[3] = {"input_layer", "hidden_layer", "output_layer"};
    Linear* layers[3] = {&l1, &l2, &l3};
    for (int i = 0; i < 3; ++i) {
        if (!layers[i]->load(cJSON_GetObjectItemCaseSensitive(root, names[i]))) {
            cJSON_Delete(root);
            return fail(std::string("bad layer in weights: ") + names[i].c_str());
        }
    }
    if (l1.in != 784 || l2.in != l1.out || l3.in != l2.out) {
        cJSON_Delete(root);
        return fail("unexpected layer shapes");
    }
    int num_classes = l3.out;
    cJSON_Delete(root);

    // --- Decode image ---
    unsigned char* rgba = nullptr;
    unsigned w = 0, h = 0;
    unsigned err = lodepng_decode32_file(&rgba, &w, &h, argv[2]);
    if (err) return fail(lodepng_error_text(err));
    if (w == 0 || h == 0) {
        free(rgba);
        return fail("empty image");
    }

    // Grayscale (ITU-R 601-2 luma), bilinearly resampled to 28x28.
    const int S = 28;
    std::vector<double> x(S * S);
    for (int dy = 0; dy < S; ++dy) {
        double sy = (dy + 0.5) * (double)h / S - 0.5;
        int y0 = (int)std::floor(sy);
        double fy = sy - y0;
        for (int dx = 0; dx < S; ++dx) {
            double sx = (dx + 0.5) * (double)w / S - 0.5;
            int x0 = (int)std::floor(sx);
            double fx = sx - x0;
            int ys[2] = {y0, y0 + 1};
            int xs[2] = {x0, x0 + 1};
            double ws[2][2] = {{(1 - fx) * (1 - fy), fx * (1 - fy)},
                               {(1 - fx) * fy, fx * fy}};
            double g = 0.0;
            for (int ny = 0; ny < 2; ++ny) {
                int yy = ys[ny] < 0 ? 0 : (ys[ny] >= (int)h ? (int)h - 1 : ys[ny]);
                for (int nx = 0; nx < 2; ++nx) {
                    int xx = xs[nx] < 0 ? 0 : (xs[nx] >= (int)w ? (int)w - 1 : xs[nx]);
                    const unsigned char* p = &rgba[((size_t)yy * w + xx) * 4];
                    double lum = 0.299 * p[0] + 0.587 * p[1] + 0.114 * p[2];
                    g += lum * ws[ny][nx];
                }
            }
            // Standard MNIST normalization.
            x[(size_t)dy * S + dx] = (g / 255.0 - 0.1307) / 0.3081;
        }
    }
    free(rgba);

    // --- Forward pass ---
    std::vector<double> h1, h2, logits;
    l1.apply(x, h1);  reLu(h1);
    l2.apply(h1, h2); reLu(h2);
    l3.apply(h2, logits);

    int best = 0;
    for (int i = 1; i < num_classes; ++i)
        if (logits[i] > logits[best]) best = i;

    printf("%d\n", best);
    return 0;
}

